function Dashboard({dash}:any){if(!dash)return <div className="panel">Loading…</div>;const vals=['mobile','desktop','tablet'].map(k=>({label:k,value:dash.analytics.reduce((a:any,x:any)=>a+Number(x[k]||0),0)}));const total=vals.reduce((a,x)=>a+x.value,0)||1;const gradient=vals.map((x,i)=>`${['#36b37e','#4c8bf5','#f5b64c'][i]} ${(vals.slice(0,i).reduce((a,y)=>a+y.value,0)/total)*360}deg ${(vals.slice(0,i+1).reduce((a,y)=>a+y.value,0)/total)*360}deg`).join(',');return <div className="dash"><div className="stat"><small>TODAY</small><b>{dash.analytics[0]?.visitors||0}</b><span>unique visitors</span></div><div className="stat"><small>7 DAYS</small><b>{dash.analytics.slice(0,7).reduce((a:any,x:any)=>a+x.visitors,0)}</b><span>unique visitors</span></div><div className="stat"><small>30 DAYS</small><b>{dash.analytics.slice(0,30).reduce((a:any,x:any)=>a+x.visitors,0)}</b><span>unique visitors</span></div><div className="panel devicePanel"><h3>Devices</h3><div className="deviceChart"><div className="pie" style={{background:`conic-gradient(${gradient})`}}><div>{total}<small>visits</small></div></div><div className="legend">{vals.map((x,i)=><div key={x.label}><i style={{background:['#36b37e','#4c8bf5','#f5b64c'][i]}}/><b>{x.label}</b><span>{x.value}</span></div>)}</div></div></div></div>}

function Admin(){const[user,setUser]=useState<any>(null),[tab,setTab]=useState('dashboard'),[dash,setDash]=useState<any>(null),[photos,setPhotos]=useState<any[]>([]),[services,setServices]=useState<any[]>([]),[videos,setVideos]=useState<any[]>([]),[admins,setAdmins]=useState<any[]>([]),[careers,setCareers]=useState<any[]>([]),[homepage,setHomepage]=useState<any>({hero:{count:4,source:'latest_instagram',photo_ids:[],interval:7,transition:'normal'},gallery:{mode:'distribution',distribution:{},photo_ids:[],published:true},strip:{photo_ids:[],interval:6,speed:'normal'},photos:[]}),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[showLoginPassword,setShowLoginPassword]=useState(false);const load=()=>{api('/api/admin/services').then(setServices).catch(()=>{});api('/api/admin/photos').then(setPhotos).catch(()=>{});api('/api/admin/videos').then(setVideos).catch(()=>{});api('/api/admin/careers').then(setCareers).catch(()=>{});api('/api/admin/homepage').then(setHomepage).catch(()=>{});if(user?.role==='owner')api('/api/admin/admins').then(setAdmins).catch(()=>{});api('/api/admin/dashboard').then(setDash).catch(()=>{})};useEffect(()=>{api('/api/me').then(u=>{setUser(u)}).catch(()=>{})},[]);useEffect(()=>{if(user)load()},[user]);if(!user)return <><NoticeHost/><div className="login"><form className="panel" onSubmit={async e=>{e.preventDefault();setBusy(true);try{setUser(await api('/api/login',{method:'POST',body:JSON.stringify({email,password})}))}catch(e:any){notify(e.message)}finally{setBusy(false)}}}><small>PRIVATE ADMIN</small><h2>Impression Photography</h2><input className="input loginInput" autoComplete="username" type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} required/><div className="passwordField"><input className="input loginInput" autoComplete="current-password" type={showLoginPassword?'text':'password'} placeholder="Password" value={password} onChange={e=>setPassword(e.target.value)} required/><button type="button" className="passwordToggle" onClick={()=>setShowLoginPassword(x=>!x)}>{showLoginPassword?'Hide':'Show'}</button></div><button className="btn light" disabled={busy}>{busy?'Signing in…':'Sign in'}</button><a className="muted setupLink" href="/admin/setup">First-time Owner setup</a></form></div></>;const tabs:any[]=[['dashboard','Dashboard',BarChart3],['gallery','Gallery & Curation',FolderOpen],['homepage','Homepage',Settings],['services','Catalogue',Settings],['videos','Videos',Play],['careers','Careers',Mail],...(user.role==='owner'?[['admins','Admins',Shield]]:[])];return <><NoticeHost/><div className="admin"><aside><a className="brand" href="/">Impression <span>Admin</span></a>{tabs.map(([k,n,I])=><button className={tab===k?'active':''} onClick={()=>setTab(k)} key={k}><I size={17}/>{n}</button>)}<a className="adminBack" href="/"><HomeIcon size={17}/>Public website</a><button onClick={async()=>{await api('/api/logout',{method:'POST'});location.reload()}}><LogOut size={17}/>Log out</button></aside><main className="adminMain"><div className="adminTop"><div><small>CONTROL CENTER</small><h1>{tab==='gallery'?'Gallery & Curation':tab==='homepage'?'Homepage':tab[0].toUpperCase()+tab.slice(1)}</h1></div><div className="adminTopActions"><ThemeToggle/><span className="pill">{user.role==='owner'?'Owner':'Admin'}</span></div></div>{tab==='dashboard'&&<Dashboard dash={dash}/>} {tab==='gallery'&&<Photos photos={photos} services={services} refresh={load}/>} {tab==='homepage'&&<><HeroAdmin photos={homepage.photos||photos} initial={homepage.hero} refresh={load}/><DistributionEditor services={services} photos={homepage.photos||photos} refresh={load}/><StripAdmin photos={homepage.photos||photos} initial={homepage.strip} refresh={load}/></>} {tab==='services'&&<ServicesAdmin services={services} refresh={load}/>} {tab==='videos'&&<VideosAdmin videos={videos} services={services} refresh={load}/>} {tab==='careers'&&<CareersAdmin careers={careers} refresh={load}/>} {tab==='admins'&&user.role==='owner'&&<AdminsAdmin admins={admins} refresh={load}/>}</main></div></>}
function CareersPage(){const data=usePublicData();return <Careers data={data}/>;}
function App(){if(location.pathname==='/gallery'||location.pathname==='/gallery/')return <Gallery/>;if(location.pathname==='/admin/setup'||location.pathname==='/admin/setup/')return <AdminSetup/>;if(location.pathname==='/admin/invite'||location.pathname==='/admin/invite/')return <AdminInviteSetup/>;if(location.pathname==='/careers'||location.pathname==='/careers/')return <CareersPage/>;return location.pathname.startsWith('/admin')?<Admin/>:<Home/>}

createRoot(document.getElementById('root')!).render(<App/>);
